    let s = fs.readFileSync(p, 'utf8').replace('Restart yalniz negatif kontrolde olculdu ve yalniz ilk 8 olumcul satira ayni kontrol kaniti olarak baglandi; digerleri OLCULEMEDI.', 'Olumcul saptanmayan satirlarda restart uygulanamaz oldugu icin OLCULEMEDI.');
